const DEF={events:[],tasks:[],plans:[],goals:[],fin:[],alarms:[],budget:[],fixed:[],widgets:[],routine:[],fp:{income:0,save:0},prefs:{ac:'#4f7cff',mode:'auto',bg:0,stickers:['✨']}};
const stk=s=>s.startsWith('data:')?`<img src="${s}" style="width:1em;height:1em;object-fit:cover;border-radius:.25em;vertical-align:middle">`:esc(s);
