const dn=()=>S.prefs.name||me.name;
function img(f,n,cb){const r=new FileReader();r.onload=()=>{const i=new Image();i.onload=()=>{const c=document.createElement('canvas'),m=Math.min(i.width,i.height);c.width=c.height=n;c.getContext('2d').drawImage(i,(i.width-m)/2,(i.height-m)/2,m,m,0,0,n,n);cb(c.toDataURL(n>100?'image/jpeg':'image/png',.85))};i.src=r.result};r.readAsDataURL(f)}
let lx,ly,mp={x:0,y:0},chat=[],busy=false,masTmp='',masHold=0,gpts=[],gcool=0,swr=[],swx=null,swd=0,swt=0;
const pad2=n=>String(n).padStart(2,'0');
const norm=s=>String(s).toLowerCase().normalize('NFD').replace(/[\u0300-\u036f]/g,'');
const KW=[['Alimentação',/mercad|super|ifood|restaur|padaria|lanche|pizza|acougue|hortifruti|cafe/],['Transporte',/uber|99|combust|posto|gasolina|metro|onibus|estacion|pedagio/],['Moradia',/alugu|condom|energia|luz|agua|internet|gas |iptu/],['Saúde',/farmac|drog|medic|consulta|saude|dentist/],['Lazer',/cinema|netflix|spotify|bar |viagem|show|ingresso|jogo/],['Educação',/curso|escola|faculdade|livro|mensalidade/],['Compras',/loja|amazon|shopee|magalu|mercado livre|roupa/],['Renda',/salar|rendimento|pagamento recebido|pix recebido|freela/]];
function categorize(d){const n=norm(d)+' ';for(const[k,r]of KW)if(r.test(n))return k;return 'Geral'}
/* ---------- Importar planilhas ---------- */
const IMPF={fin:[['date','Data'],['desc','Descrição'],['val','Valor'],['cat','Categoria'],['type','Tipo (entrada/saída)']],tasks:[['title','Título'],['due','Prazo'],['pri','Prioridade']],events:[['title','Título'],['date','Data'],['time','Hora']],goals:[['title','Título'],['target','Alvo'],['cur','Atual'],['unit','Unidade']]};
const IMPR={fin:{date:/data|date|dia/,desc:/desc|hist|nome|estab|titulo|lanc|item/,val:/valor|value|amount|quantia|montante|total/,cat:/categ/,type:/tipo|type|natur|d\/c|cred/},tasks:{title:/tarefa|titulo|nome|desc|atividade/,due:/prazo|venc|data|entrega/,pri:/prior/},events:{title:/evento|titulo|nome|desc|compromisso/,date:/data|date|dia/,time:/hora|time|horario/},goals:{title:/meta|titulo|nome|objetivo/,target:/alvo|meta|total|objetivo|valor/,cur:/atual|progress|feito|realiz|acumul/,unit:/unid/}};
let IMP={dest:'fin',raw:[],rows:[],head:[],map:{},file:'',pos:'in',bud:false,direct:null,rules:[],skip:[],dord:'dmy',note:'',busy:false};
function pv(v){if(typeof v==='number')return v;let s=String(v).trim();if(!s)return NaN;const neg=/^\(.*\)$|^-|-$/.test(s);s=s.replace(/[^\d.,]/g,'');if(s.includes(','))s=s.replace(/\./g,'').replace(',','.');else if((s.match(/\./g)||[]).length>1)s=s.replace(/\./g,'');const n=parseFloat(s);return neg?-n:n}
function pd(v){if(v instanceof Date&&!isNaN(v)){v=new Date(v.getTime()+12*3600e3);return v.getFullYear()+'-'+pad2(v.getMonth()+1)+'-'+pad2(v.getDate())}
 if(typeof v==='number'&&v>20000&&v<80000)return new Date(Math.round((v-25569)*864e5)).toISOString().slice(0,10);
 const s=String(v).trim();let m=s.match(/^(\d{4})[\/.-](\d{1,2})[\/.-](\d{1,2})/);if(m)return m[1]+'-'+pad2(m[2])+'-'+pad2(m[3]);
 m=s.match(/^(\d{1,2})[\/.-](\d{1,2})[\/.-](\d{2,4})/);if(m){const y=m[3].length==2?'20'+m[3]:m[3],a=IMP.dord==='mdy'?[m[2],m[1]]:[m[1],m[2]];return y+'-'+pad2(a[1])+'-'+pad2(a[0])}
 return today()}
function pt(v){const m=String(v).match(/(\d{1,2}):(\d{2})/);return m?pad2(m[1])+':'+m[2]:''}
function parseCSV(t){t=t.replace(/^\uFEFF/,'');const f=t.split('\n')[0],dl=(f.match(/;/g)||[]).length>(f.match(/,/g)||[]).length?';':(f.includes('\t')?'\t':',');const R=[];let r=[],c='',q=false;for(let i=0;i<t.length;i++){const ch=t[i];if(q){if(ch=='"'){if(t[i+1]=='"'){c+='"';i++}else q=false}else c+=ch}else if(ch=='"')q=true;else if(ch==dl){r.push(c);c=''}else if(ch=='\n'||ch=='\r'){if(ch=='\r'&&t[i+1]=='\n')i++;r.push(c);R.push(r);r=[];c=''}else c+=ch}if(c||r.length){r.push(c);R.push(r)}return R}
function setHeader(i){const R=IMP.raw;if(i<0||i>=R.length){const w=Math.max(...R.map(r=>r.length));IMP.head=Array.from({length:w},(_,j)=>'Coluna '+(j+1));IMP.rows=R.slice()}else{IMP.head=R[i].map(String);IMP.rows=R.slice(i+1)}}
function detectHeader(R){if(Math.max(...R.map(r=>r.length))<2)return -1;for(let i=0;i<Math.min(15,R.length-1);i++){const c=R[i].filter(x=>String(x).trim());if(c.length>=2&&c.filter(x=>typeof x!=='number'&&!(x instanceof Date)&&isNaN(pv(x))).length>=c.length*.6)return i}return 0}
function loadRaw(R,label){R=R.filter(r=>r.some(x=>String(x).trim()));if(!R.length){toast('Arquivo vazio');return}IMP.raw=R;IMP.file=label;IMP.direct=null;IMP.rules=[];IMP.skip=[];IMP.note='';IMP.dord='dmy';setHeader(detectHeader(R));automap();render()}
async function readSheet(f){const buf=await f.arrayBuffer();let R,label=f.name;
 if(/\.xlsx?$/i.test(f.name)){if(!window.XLSX){toast('Leitor de Excel não carregou — salve a planilha como CSV');return}const wb=XLSX.read(buf,{type:'array',cellDates:true});let best=[],bn='';for(const n of wb.SheetNames){const r=XLSX.utils.sheet_to_json(wb.Sheets[n],{header:1,raw:true,defval:''});if(r.length>best.length){best=r;bn=n}}R=best;if(wb.SheetNames.length>1)label+=' · '+bn}
 else{let t;try{t=new TextDecoder('utf-8',{fatal:true}).decode(buf)}catch(e){t=new TextDecoder('windows-1252').decode(buf)}R=/\.(csv|tsv)$/i.test(f.name)?parseCSV(t):t.split(/\r?\n/).map(l=>[l])}
 loadRaw(R,label)}
function automap(){IMP.map={};const used=new Set(),H=IMP.head.map(norm);for(const[k]of IMPF[IMP.dest]){const i=H.findIndex((h,j)=>!used.has(j)&&IMPR[IMP.dest][k].test(h));if(i>=0){IMP.map[k]=i;used.add(i)}}}
function ruleCat(d){const n=norm(d),r=IMP.rules.find(x=>n.includes(norm(x.contains)));return r?r.cat:''}
function impItems(){if(IMP.direct)return IMP.direct;const M=IMP.map,g=(r,k)=>M[k]==null?'':r[M[k]],D=IMP.dest,out=[],sk=IMP.skip.map(norm);
 for(const r of IMP.rows){if(sk.length&&r.some(x=>{const n=norm(x);return n&&sk.some(p=>n.includes(p))}))continue;let o;
  if(D==='fin'){const desc=String(g(r,'desc')).trim(),raw=pv(g(r,'val'));if(!desc||isNaN(raw))continue;
   const type=M.type!=null?(/entr|rec|cred|rend|^in|\+/.test(norm(g(r,'type')))?'in':'out'):((raw<0)===(IMP.pos==='in')?'out':'in');
   o={type,desc,val:Math.abs(raw),cat:String(g(r,'cat')).trim()||ruleCat(desc)||categorize(desc),date:M.date!=null?pd(g(r,'date')):today()}}
  else if(D==='tasks'){const t=String(g(r,'title')).trim();if(!t)continue;const p=norm(g(r,'pri')),d=g(r,'due');o={title:t,due:d===''?'':pd(d),pri:/alt|high|urg/.test(p)?'a':/baix|low/.test(p)?'b':'m',done:false}}
  else if(D==='events'){const t=String(g(r,'title')).trim();if(!t)continue;o={title:t,date:pd(g(r,'date')),time:pt(g(r,'time'))}}
  else{const t=String(g(r,'title')).trim(),tg=pv(g(r,'target'));if(!t||isNaN(tg)||tg<=0)continue;o={title:t,target:tg,cur:pv(g(r,'cur'))||0,unit:String(g(r,'unit'))}}
  out.push(o)}return out}
function doImport(){const it=impItems(),D=IMP.dest;it.forEach(o=>S[D].push({id:uid(),...o}));
 if(D==='fin'&&IMP.bud){const c={},mo=new Set(it.map(o=>o.date.slice(0,7))).size||1;it.filter(o=>o.type==='out').forEach(o=>c[o.cat]=(c[o.cat]||0)+o.val);
  Object.entries(c).forEach(([k,v])=>{const x=S.budget.find(b=>b.cat.toLowerCase()===k.toLowerCase()),l=Math.ceil(v/mo*1.1);if(x)x.limit=l;else S.budget.push({id:uid(),cat:k,limit:l})})}
 IMP.raw=[];IMP.rows=[];IMP.direct=null;IMP.file='';IMP.note='';view=D;save();toast(it.length+' itens importados')}
function prevTxt(o){const D=IMP.dest;return D==='fin'?`${o.date} · ${o.desc} · ${o.type==='in'?'+':'−'}${brl(o.val)} · ${o.cat}`:D==='tasks'?`${o.title}${o.due?' · '+o.due:''}`:D==='events'?`${o.date} ${o.time} ${o.title}`:`${o.title}: ${o.cur}/${o.target} ${o.unit}`}
/* IA: entende o arquivo (tabela bagunçada ou texto livre) e configura a importação */
function normDirect(D,x){const s=v=>String(v==null?'':v).trim();
 if(D==='fin'){const desc=s(x.description||x.title),val=Math.abs(+x.value);if(!desc||isNaN(val))return null;return{type:x.type==='in'?'in':'out',desc,val,cat:s(x.category)||ruleCat(desc)||categorize(desc),date:x.date?pd(x.date):today()}}
 if(D==='tasks'){const t=s(x.title||x.description);if(!t)return null;const p=norm(x.priority||'');return{title:t,due:x.due?pd(x.due):'',pri:/^a|alt/.test(p)?'a':/^b|baix/.test(p)?'b':'m',done:false}}
 if(D==='events'){const t=s(x.title||x.description);if(!t)return null;return{title:t,date:x.date?pd(x.date):today(),time:pt(x.time||'')}}
 const t=s(x.title),tg=+x.target;if(!t||!(tg>0))return null;return{title:t,target:tg,cur:+x.current||0,unit:s(x.unit)}}
let IDL={msgs:[],busy:false};
const IDERR=e=>e&&(e.code==='nokey'||e.code==='badkey')?'Configure a chave da IA em Ajustes.':e&&e.code==='not_granted'?'Permita o uso da IA para continuar.':e&&e.code==='none'?'A IA não está disponível.':e&&e.code==='rate_limited'?'Muitas mensagens seguidas, espere um pouquinho.':'Não consegui analisar o arquivo. Tente de novo.';
function impTools(onDone){const s={type:'string'},DE={type:'string',enum:['fin','tasks','events','goals']};return [
 {name:'configure_import',description:'Configura a importação quando o conteúdo é uma TABELA (aplicada depois a todas as linhas). Sempre envie a configuração completa.',inputSchema:{type:'object',properties:{dest:DE,header_row:{type:'integer',description:'índice da linha de cabeçalho; -1 se não houver'},columns:{type:'object',description:'índice (inteiro) da coluna de cada campo; omita o que não existir',properties:Object.fromEntries(['date','desc','val','cat','type','title','due','pri','time','target','cur','unit'].map(k=>[k,{type:'integer'}]))},positive_means:{type:'string',enum:['in','out']},date_order:{type:'string',enum:['dmy','mdy','ymd']},skip_if_contains:{type:'array',items:s},category_rules:{type:'array',items:{type:'object',properties:{contains:s,cat:s}}}},required:['dest','header_row','columns']},
  execute:i=>{if(IMPF[i.dest])IMP.dest=i.dest;if(Number.isInteger(i.header_row))setHeader(i.header_row);IMP.map={};const ok=IMPF[IMP.dest].map(f=>f[0]);Object.entries(i.columns||{}).forEach(([k,v])=>{if(Number.isInteger(v)&&v>=0&&ok.includes(k))IMP.map[k]=v});
   IMP.pos=i.positive_means==='out'?'out':'in';IMP.dord=['dmy','mdy','ymd'].includes(i.date_order)?i.date_order:'dmy';IMP.skip=(i.skip_if_contains||[]).filter(Boolean).slice(0,20);IMP.rules=(i.category_rules||[]).filter(r=>r&&r.contains&&r.cat).slice(0,60);IMP.direct=null;onDone();return 'ok: '+impItems().length+' itens válidos'}},
 {name:'extract_items',description:'Entrega itens já normalizados quando o conteúdo NÃO é uma tabela (texto livre, lista, extrato colado).',inputSchema:{type:'object',properties:{dest:DE,items:{type:'array',items:{type:'object',properties:{title:s,description:s,date:s,time:s,due:s,priority:s,value:{type:'number'},type:s,category:s,target:{type:'number'},current:{type:'number'},unit:s}}}},required:['dest','items']},
  execute:i=>{if(IMPF[i.dest])IMP.dest=i.dest;IMP.direct=(i.items||[]).slice(0,150).map(x=>normDirect(IMP.dest,x)).filter(Boolean);onDone();return 'ok: '+IMP.direct.length+' itens'}}]}
function impPrompt(){const n=IMP.raw.length<=150?150:60,lines=IMP.raw.slice(0,n).map((r,i)=>i+': '+r.slice(0,20).map(c=>(c instanceof Date?pd(c):String(c)).replace(/\s+/g,' ').slice(0,60)).join(' | ')).join('\n').slice(0,12000);
 const st=`destino=${IMP.dest}; ${IMP.direct?'itens extraídos diretamente':'colunas mapeadas '+JSON.stringify(IMP.map)+' (cabeçalho atual: '+IMP.head.join(' | ').slice(0,200)+')'}; valores positivos = ${IMP.pos}; ignorar linhas com ${JSON.stringify(IMP.skip)}; ${IMP.rules.length} regras de categoria; ${impItems().length} itens válidos na prévia.`;
 const tr=IDL.msgs.slice(-12).map(m=>(m.r==='u'?'Usuário: ':'Você: ')+m.t).join('\n')||'(o usuário acabou de enviar o arquivo)';
 return `Você ajuda o usuário a importar um arquivo para um app de gestão pessoal, conversando em português do Brasil (frases curtas). O arquivo tem ${IMP.raw.length} linhas; abaixo estão as ${Math.min(n,IMP.raw.length)} primeiras (formato "índice: coluna | coluna | ...").\n\n${lines}\n\nDestinos: fin (lançamentos: data, descrição, valor, categoria, tipo), tasks (título, prazo, prioridade), events (título, data, hora), goals (título, alvo, atual, unidade).\nEstado atual da importação (começou com um palpite automático que pode estar errado): ${st}\n\nRegras:\n- Se for uma tabela, chame configure_import: header_row (cabeçalho real), índice de cada coluna, positive_means (em extratos bancários valores negativos são saídas), date_order, skip_if_contains (totais, saldos, cabeçalhos repetidos) e category_rules (palavras-chave das descrições -> categoria em português como Alimentação, Transporte, Moradia, Saúde, Lazer, Educação, Compras, Renda, Assinaturas, Impostos).\n- Se NÃO for tabela, chame extract_items com os itens normalizados (datas AAAA-MM-DD, hora HH:MM, valores positivos em reais).\n- Se houver ambiguidade relevante (destino, sinal dos valores, formato de data, o que ignorar), NÃO chame ferramenta: faça UMA pergunta curta ao usuário e espere a resposta.\n- Se o usuário pedir ajustes, chame a ferramenta de novo com a configuração completa atualizada.\n- Depois de chamar a ferramenta, resuma em uma ou duas frases o que entendeu e o que ignorou.\n\nConversa até agora:\n${tr}`}
function idlgEl(){let el=$('#idlg');if(!el){el=document.createElement('div');el.id='idlg';el.innerHTML='<div class="box glass"><div class="ch"><b>✨ Importar com IA</b><button class="x" data-a="idx">✕</button></div><div id="idm"></div><div id="idb"></div><div class="cin"><input id="idi" placeholder="Responda ou peça um ajuste…" autocomplete="off"><button class="pri" data-a="idsend">➤</button></div></div>';document.body.append(el);$('#idi').addEventListener('keydown',e=>{if(e.key==='Enter')idSend()})}return el}
function addIMsg(r,t){const d=document.createElement('div');d.className='mg '+r;d.textContent=t;$('#idm').append(d);$('#idm').scrollTop=1e9;return d}
function idButtons(){const n=IMP.raw.length?impItems().length:0;$('#idb').innerHTML=n?`<button class="pri" data-a="idimport">Importar ${n} itens</button><button class="pri" data-a="idx" style="background:var(--mu)">Revisar prévia</button>`:''}
async function idTurn(text){if(text){IDL.msgs.push({r:'u',t:text});addIMsg('u',text)}
 IDL.busy=true;IMP.busy=true;const b=addIMsg('b','…');let done=false;
 try{const sm=await claude.use('sample');if(!sm)throw{code:'none'};
  const r=await sm(impPrompt(),{cache:false,tools:impTools(()=>{done=true}),onText:({text})=>{b.textContent=text||'…'}});
  const t=(r.text||'').trim();b.textContent=t||(done?'Pronto! Veja a prévia.':'Não entendi bem. O que você quer importar?');if(done)IMP.note=b.textContent;IDL.msgs.push({r:'b',t:b.textContent})}
 catch(e){b.textContent=IDERR(e)}
 IDL.busy=false;IMP.busy=false;idButtons();render()}
function aiImport(){if(!IMP.raw.length||IDL.busy)return;idlgEl().hidden=false;IDL.msgs=[];$('#idm').innerHTML='';$('#idb').innerHTML='';idTurn('')}
function idSend(){const i=$('#idi'),t=i.value.trim();if(!t||IDL.busy)return;i.value='';idTurn(t)}
function impCard(){const D=IMP.dest,F=IMPF[D],has=IMP.raw.length>0,items=has?impItems():[],map=has&&!IMP.direct;
 return `<div class="glass card" id="imp"><h2>📥 Importar arquivo</h2><div class="mu" style="margin-bottom:8px">Envie .xlsx, .xls, .csv ou .txt — ou cole um texto — e a IA organiza as informações no app (categorias, datas, valores e linhas de total).</div>
 <div class="seg">${[['fin','💰 Finanças'],['tasks','✅ Tarefas'],['events','📅 Eventos'],['goals','🎯 Metas']].map(([k,l])=>`<button class="${D===k?'on':''}" data-a="idest" data-v="${k}">${l}</button>`).join('')}</div>
 <div class="seg"><button data-a="ifile">📄 ${IMP.file?esc(IMP.file):'Escolher arquivo'}</button></div>
 <details style="margin-bottom:10px"><summary class="mu" style="cursor:pointer">Ou cole um texto (extrato, lista de tarefas, anotações…)</summary><textarea id="ipaste" rows="4" style="width:100%;margin-top:8px;border-radius:14px;padding:10px;background:var(--in);border:1px solid var(--gb);color:var(--tx);font:inherit"></textarea><button class="pri" data-a="ipaste" style="margin-top:6px">Ler texto</button></details>`+
 (has?`<button class="pri" data-a="iai" ${IMP.busy?'disabled':''} style="width:100%;margin-bottom:10px">✨ ${IMP.busy?'Analisando com IA…':'Organizar com IA'}</button>${IMP.note?`<div class="row"><div class="g mu">✨ ${esc(IMP.note)}</div></div>`:''}`:'')+
 (map?`<div class="mu" style="margin-bottom:6px">Colunas associadas (ajuste se precisar):</div>${F.map(([k,l])=>`<div class="row"><div class="g t">${l}</div><select data-m="${k}"><option value="">— ignorar —</option>${IMP.head.map((h,i)=>`<option value="${i}" ${IMP.map[k]===i?'selected':''}>${esc(h||'Coluna '+(i+1))}</option>`).join('')}</select></div>`).join('')}
 ${F.some(f=>['date','due'].includes(f[0]))?`<div class="row"><div class="g t">Formato das datas</div><select data-m="_dord">${[['dmy','dia/mês/ano'],['mdy','mês/dia/ano'],['ymd','ano-mês-dia']].map(([v,l])=>`<option value="${v}" ${IMP.dord===v?'selected':''}>${l}</option>`).join('')}</select></div>`:''}
 ${D==='fin'?`<div class="row"><div class="g t">Valores positivos são</div><select data-m="_pos"><option value="in" ${IMP.pos==='in'?'selected':''}>Entradas</option><option value="out" ${IMP.pos==='out'?'selected':''}>Saídas</option></select></div>`:''}`:'')+
 (has&&D==='fin'?`<div class="row"><div class="g t">Sugerir orçamento por categoria (média mensal +10%)</div><input type="checkbox" id="ibud" style="flex:none" ${IMP.bud?'checked':''}></div>`:'')+
 (has?`<div class="mu" style="margin:8px 0">Prévia · ${items.length} itens${IMP.direct?'':` (${IMP.rows.length-items.length} linhas ignoradas)`}</div>${items.slice(0,6).map(o=>`<div class="row"><div class="g mu">${esc(prevTxt(o))}</div></div>`).join('')}<button class="pri" data-a="idoit" ${items.length?'':'disabled'}>Importar ${items.length} itens</button>`:'')+`</div>`}
