let _ac;
addEventListener('pointerdown',()=>{try{_ac=_ac||new AudioContext();_ac.resume()}catch(e){}},{once:true});
const SND=[['bip','Bip clássico'],['sino','Sino'],['harpa','Harpa'],['digital','Digital'],['suave','Carrilhão suave'],['sirene','Sirene']];
function playSnd(id){id=id||S.prefs.snd||'bip';const vol=(S.prefs.vol??80)/100;
 const uf=id==='custom'?S.prefs.sndFile:/^u:/.test(id)?(((S.prefs.lib||[]).find(l=>'u:'+l.id===id))||{}).data:null;if(uf){try{window._au&&window._au.pause()}catch(e){}const a=window._au=new Audio(uf);a.volume=vol;a.play().catch(()=>{});setTimeout(()=>a.pause(),15000);return}
 try{const c=_ac||(_ac=new AudioContext());c.resume&&c.resume();
  const tone=(f,t,d,type='sine',v=.3)=>{const o=c.createOscillator(),g=c.createGain(),T=c.currentTime+t;o.type=type;o.frequency.value=f;g.gain.setValueAtTime(0,T);g.gain.linearRampToValueAtTime(v*vol,T+.02);g.gain.exponentialRampToValueAtTime(.0001,T+d);o.connect(g);g.connect(c.destination);o.start(T);o.stop(T+d+.05)};
  if(id==='sino')[0,1.2,2.4].forEach(t=>{tone(660,t,1.1);tone(1320,t,.7,'sine',.12);tone(1980,t,.4,'sine',.06)});
  else if(id==='harpa')[523,659,784,1047,784,659,523,659,784,1047].forEach((f,i)=>tone(f,i*.18,.6,'triangle',.28));
  else if(id==='digital')for(let i=0;i<8;i++)tone(i%2?1400:1000,i*.14,.1,'square',.12);
  else if(id==='suave')[784,988,1175,988].forEach((f,i)=>tone(f,i*.35,1.2,'sine',.25));
  else if(id==='sirene'){const o=c.createOscillator(),g=c.createGain();o.type='sawtooth';g.gain.value=.12*vol;o.frequency.setValueAtTime(600,c.currentTime);for(let i=0;i<4;i++){o.frequency.linearRampToValueAtTime(1100,c.currentTime+i+.5);o.frequency.linearRampToValueAtTime(600,c.currentTime+i+1)}o.connect(g);g.connect(c.destination);o.start();o.stop(c.currentTime+4)}
  else [0,.4,.8].forEach(t=>tone(880,t,.25,'sine',.4))}catch(e){}}
function sndName(id){const x=id||S.prefs.snd||'bip',n=x==='custom'?'Meu som':/^u:/.test(x)?((((S.prefs.lib||[]).find(l=>'u:'+l.id===x))||{}).name||'Áudio'):(SND.find(s=>s[0]===x)||[0,'Bip clássico'])[1];return id?n:'Padrão · '+n}
function sndOpts(sel){return '<option value="">Som padrão</option>'+SND.map(([k,l])=>`<option value="${k}" ${sel===k?'selected':''}>${l}</option>`).join('')+(S.prefs.sndFile?`<option value="custom">Meu som${S.prefs.sndName?' · '+esc(S.prefs.sndName):''}</option>`:'')+(S.prefs.lib||[]).map(l=>`<option value="u:${l.id}" ${sel==='u:'+l.id?'selected':''}>🎵 ${esc(l.name)}</option>`).join('')}
function sndCard(){const p=S.prefs,cur=p.snd||'bip';return `<div class="glass card"><h2>🔔 Som dos alarmes</h2><div class="seg">${SND.map(([k,l])=>`<button class="${cur===k?'on':''}" data-a="snd" data-v="${k}">${l}</button>`).join('')}${p.sndFile?`<button class="${cur==='custom'?'on':''}" data-a="snd" data-v="custom">Meu som</button>`:''}</div>
 <div class="seg"><button data-a="sndup">⬆️ Enviar meu som</button>${p.sndFile?'<button data-a="sndrm">Remover meu som</button>':''}<button data-a="psnd" data-v="">▶ Ouvir</button></div>
 <div class="mu">${p.sndFile?'Arquivo: '+esc(p.sndName||''):'Aceita MP3, WAV ou OGG de até 1,5 MB.'} Cada alarme pode ter seu próprio som.</div>
 <div class="row"><div class="g t">Volume</div><input type="range" min="0" max="100" value="${p.vol??80}" data-sl="vol"></div></div>`}
function masSVG(){const m=S.prefs.mas||{},c=m.c||'#ffadd0',c2=m.c2||'#ffffff',fc=m.fc||'#ff4f7b',pc=m.ec||'#1c1f4a',sh=m.sh||'puff',ac=m.ac||'none',mo=masTmp||m.mo||'happy',P=sh==='puff',px=m.px||[],mk=m.mk||[],k1=m.mk1||'#111111',k2=m.mk2||'#7b2cff',pk=m.pkc||'#ff2d95',ex=P?[41,59]:[36,64],ey=P?48:52,mc=mk.includes('lips')?k2:'#c2334d',mc2=mk.includes('lips')?k2:pc;
 const E={cat:`<path d="M16 42L20 6L46 24Z M84 42L80 6L54 24Z" fill="${c}"/>`,bunny:`<ellipse cx="34" cy="12" rx="9" ry="22" fill="${c}"/><ellipse cx="66" cy="12" rx="9" ry="22" fill="${c}"/><ellipse cx="34" cy="14" rx="4" ry="14" fill="#ffb3c7"/><ellipse cx="66" cy="14" rx="4" ry="14" fill="#ffb3c7"/>`,robot:`<rect x="48" y="4" width="4" height="16" fill="${c}"/><circle cx="50" cy="5" r="5" fill="#ff6b9a"/>`}[sh]||'';
 const B={puff:`<ellipse cx="50" cy="56" rx="38" ry="36"/>`,blob:`<path d="M50 20C80 20 92 44 90 66C88 86 70 94 50 94C30 94 12 86 10 66C8 44 20 20 50 20Z"/>`,cat:`<ellipse cx="50" cy="58" rx="40" ry="36"/>`,bunny:`<ellipse cx="50" cy="60" rx="38" ry="34"/>`,robot:`<rect x="12" y="22" width="76" height="68" rx="20"/>`,ghost:`<path d="M12 94V50C12 28 28 14 50 14S88 28 88 50V94L74 84L62 94L50 84L38 94L26 84Z"/>`}[sh]||'';
 const limbs=P?`<ellipse cx="31" cy="91" rx="17" ry="9" transform="rotate(-12 31 91)" fill="${fc}"/><ellipse cx="69" cy="91" rx="17" ry="9" transform="rotate(12 69 91)" fill="${fc}"/><ellipse cx="8" cy="60" rx="12" ry="9" transform="rotate(-35 8 60)" fill="${c}"/><ellipse cx="92" cy="60" rx="12" ry="9" transform="rotate(35 92 60)" fill="${c}"/>`:'';
 const belly=(P?m.bel!==true:m.bel===false)?'':`<ellipse cx="50" cy="78" rx="22" ry="13" fill="${c2}" opacity=".55"/>`;
 const eye=x=>`<ellipse class="ew" data-r="2.2" cx="${x}" cy="48" rx="6.5" ry="11" fill="${pc}"/><circle class="pp" cx="${x}" cy="43" r="3.6" fill="#fff"/><ellipse cx="${x}" cy="55" rx="4" ry="3.4" fill="#4d6bff" opacity=".6"/>`;
 const eyes=P?`<g class="eyes">${eye(41)}${eye(59)}</g>`:`<g class="eyes"><circle class="ew" cx="36" cy="52" r="11" fill="#fff"/><circle class="pp" cx="36" cy="52" r="5.5" fill="${pc}"/><circle class="ew" cx="64" cy="52" r="11" fill="#fff"/><circle class="pp" cx="64" cy="52" r="5.5" fill="${pc}"/></g>`;
 const blush=m.bl===false?'':P?'<ellipse cx="27" cy="62" rx="7" ry="4" fill="#ff6b8f" opacity=".6"/><ellipse cx="73" cy="62" rx="7" ry="4" fill="#ff6b8f" opacity=".6"/>':'<circle cx="22" cy="68" r="6" fill="#ff8fa8" opacity=".5"/><circle cx="78" cy="68" r="6" fill="#ff8fa8" opacity=".5"/>';
 const mouth=(P?{happy:`<path d="M44 66Q50 77 56 66Z" fill="${mc}"/>`,neutral:`<path d="M45 69H55" stroke="${mc}" stroke-width="3" stroke-linecap="round"/>`,wow:`<ellipse cx="50" cy="69" rx="3.5" ry="4.5" fill="${mc}"/>`}:{happy:`<path d="M41 69Q50 78 59 69" stroke="${mc2}" stroke-width="3" fill="none" stroke-linecap="round"/>`,neutral:`<path d="M43 71H57" stroke="${mc2}" stroke-width="3" stroke-linecap="round"/>`,wow:`<ellipse cx="50" cy="72" rx="4" ry="5" fill="${mc2}"/>`})[mo]||'';
 const A={hat:`<path d="M34 26L50 -6L66 26Z" fill="#ff6b9a"/><circle cx="50" cy="-6" r="4.5" fill="#ffd166"/>`,crown:`<path d="M30 28L34 8L43 19L50 5L57 19L66 8L70 28Z" fill="#ffd166" stroke="#e0a800"/>`,glasses:`<circle cx="36" cy="52" r="14" fill="none" stroke="#14213a" stroke-width="3"/><circle cx="64" cy="52" r="14" fill="none" stroke="#14213a" stroke-width="3"/><path d="M48 50Q50 47 52 50" fill="none" stroke="#14213a" stroke-width="3"/>`,bow:`<path d="M50 88L34 78V98ZM50 88L66 78V98Z" fill="#ff6b9a"/><circle cx="50" cy="88" r="4" fill="#ff3d7f"/>`,phones:`<path d="M14 56C14 14 86 14 86 56" fill="none" stroke="#444" stroke-width="6"/><rect x="8" y="48" width="12" height="20" rx="6" fill="#444"/><rect x="80" y="48" width="12" height="20" rx="6" fill="#444"/>`}[ac]||'';
 const st=(cx,cy,r)=>'<polygon points="'+[...Array(10)].map((_,i)=>{const a=Math.PI/5*i-Math.PI/2,rr=i%2?r*.45:r;return(cx+rr*Math.cos(a)).toFixed(1)+','+(cy+rr*Math.sin(a)).toFixed(1)}).join(' ')+'" fill="'+k2+'"/>';
 const sh2=mk.includes('shadow')?ex.map(x=>`<ellipse cx="${x}" cy="${ey}" rx="12" ry="15" fill="${k2}" opacity=".4"/>`).join(''):'';
 const ln=mk.includes('liner')?`<g stroke="${k1}" stroke-width="2.6" fill="none" stroke-linecap="round"><path d="M${ex[0]-8} ${ey-10}Q${ex[0]} ${ey-17} ${ex[0]+8} ${ey-10}M${ex[0]-8} ${ey-10}L${ex[0]-15} ${ey-16}"/><path d="M${ex[1]-8} ${ey-10}Q${ex[1]} ${ey-17} ${ex[1]+8} ${ey-10}M${ex[1]+8} ${ey-10}L${ex[1]+15} ${ey-16}"/></g>`:'';
 const war=mk.includes('war')?`<g stroke="${k1}" stroke-width="2.4" stroke-linecap="round"><path d="M${ex[0]-18} ${ey+10}l9 6M${ex[0]-13} ${ey+5}l9 6"/><path d="M${ex[1]+18} ${ey+10}l-9 6M${ex[1]+13} ${ey+5}l-9 6"/></g>`:'';
 const tear=mk.includes('tear')?`<path d="M${ex[0]-3} ${ey+13}Q${ex[0]-8} ${ey+21} ${ex[0]-3} ${ey+24}Q${ex[0]+2} ${ey+21} ${ex[0]-3} ${ey+13}Z" fill="${k1}"/>`:'';
 const stm=mk.includes('star')?st(ex[1]+10,ey+16,6):'';
 const pnk=(px.includes('mohawk')?`<path d="M32 30L36 2L43 24L48 -9L54 24L61 0L68 30Z" fill="${pk}" stroke="rgba(0,0,0,.25)" stroke-width="1"/>`:'')
 +(px.includes('bandana')?`<path d="M14 40Q50 14 86 40L86 46Q50 22 14 46Z" fill="#c1121f"/><circle cx="30" cy="38" r="1.6" fill="#fff"/><circle cx="50" cy="29" r="1.6" fill="#fff"/><circle cx="70" cy="38" r="1.6" fill="#fff"/>`:'')
 +(px.includes('collar')?`<path d="M24 80Q50 96 76 80" fill="none" stroke="#1b1b1b" stroke-width="6" stroke-linecap="round"/>`+[.12,.3,.5,.7,.88].map(t=>{const x=24+52*t,y=80+32*t*(1-t);return `<polygon points="${x-2.2},${y+1} ${x+2.2},${y+1} ${x},${y+7}" fill="#dcdce6"/>`}).join(''):'')
 +(px.includes('rings')?`<g fill="none" stroke="#dcdce6" stroke-width="1.8"><circle cx="11" cy="50" r="4.5"/><circle cx="89" cy="50" r="4.5"/><circle cx="13" cy="42" r="2.2"/><circle cx="87" cy="42" r="2.2"/></g>`:'')
 +(px.includes('pierce')?`<g stroke="#e8e8f2" stroke-width="2" stroke-linecap="round" fill="none"><path d="M${ex[0]-6} ${ey-18}l2-5M${ex[0]-1} ${ey-19}l1.5-5"/><circle cx="55" cy="${P?72:74}" r="2.6"/></g>`:'')
 +(px.includes('chain')?`<path d="M26 86Q50 104 74 86" fill="none" stroke="#c8c8d4" stroke-width="2.6" stroke-dasharray="3.2 1.6" stroke-linecap="round"/>`:'');
 return `<svg viewBox="0 -10 100 110">${limbs}<g fill="${c}">${B}</g>${belly}${E}${sh2}${eyes}${ln}${war}${tear}${stm}${blush}${mouth}${A}${pnk}</svg>`}
function drawMas(){const m=S.prefs.mas||{},el=$('#mas');if(!el)return;if(m.on===false){el.style.display='none';return}el.style.display='';el.style.setProperty('--ms',(m.sz||80)+'px');el.querySelector('.mb').innerHTML=masSVG();$('#chn').textContent=m.name||'Bicetinho';if(lx!==undefined)look(lx,ly)}
function look(x,y){lx=x;ly=y;document.querySelectorAll('#mas .ew').forEach(w=>{const r=w.getBoundingClientRect(),cx=r.left+r.width/2,cy=r.top+r.height/2,a=Math.atan2(y-cy,x-cx),d=Math.min(+(w.dataset.r||4.5),Math.hypot(x-cx,y-cy)/25);w.nextElementSibling.setAttribute('transform',`translate(${Math.cos(a)*d} ${Math.sin(a)*d})`)})}
function masGoto(x,y,dur,mood){const m=S.prefs.mas||{},sz=m.sz||80,el=$('#mas'),mb=el.querySelector('.mb');
 x=Math.max(8,Math.min(innerWidth-sz-8,x));y=Math.max(70,Math.min(innerHeight-sz-100,y));
 mb.style.rotate=(x>mp.x?6:-6)+'deg';mp={x,y};el.classList.add('walk');setPos(x,y,dur);masHold=Date.now()+5000;
 if(mood){masTmp=mood;drawMas();setTimeout(()=>{masTmp='';drawMas()},1500)}
 setTimeout(()=>{el.classList.remove('walk');mb.style.rotate='0deg'},dur*1000)}
function masGesture(e){const m=S.prefs.mas||{};if(m.on===false||m.gs===false||!$('#chat').hidden)return;const now=Date.now();if(now<gcool)return;
 const r=$('#mas').getBoundingClientRect(),inside=e.clientX>=r.left-20&&e.clientX<=r.right+20&&e.clientY>=r.top-20&&e.clientY<=r.bottom+20;
 if(inside){swt=now;if(swx===null){swx=e.clientX;swd=0}const dx=e.clientX-swx;
  if(Math.abs(dx)>=14){const d=Math.sign(dx);if(swd&&d!==swd)swr.push(now);swd=d;swx=e.clientX;swr=swr.filter(t=>now-t<1600);
   if(swr.length>=4){swr=[];swx=null;gcool=now+1800;const sz=m.sz||80;let tx,ty,k=0;do{tx=8+Math.random()*(innerWidth-sz-16);ty=70+Math.random()*Math.max(10,innerHeight-sz-190);k++}while(Math.hypot(tx-e.clientX,ty-e.clientY)<260&&k<20);masGoto(tx,ty,.9,'wow');return}}}
 else if(now-swt>700){swx=null;swd=0;swr=[]}
 const p=gpts[gpts.length-1];if(!p||Math.hypot(e.clientX-p.x,e.clientY-p.y)>=4){gpts.push({x:e.clientX,y:e.clientY,t:now});gpts=gpts.filter(q=>now-q.t<2000)}
 if(gpts.length>=14){const cx=gpts.reduce((a,q)=>a+q.x,0)/gpts.length,cy=gpts.reduce((a,q)=>a+q.y,0)/gpts.length;let tot=0,rad=0;
  for(let i=0;i<gpts.length;i++){const a1=Math.atan2(gpts[i].y-cy,gpts[i].x-cx);rad+=Math.hypot(gpts[i].x-cx,gpts[i].y-cy);if(i){let da=a1-Math.atan2(gpts[i-1].y-cy,gpts[i-1].x-cx);while(da>Math.PI)da-=2*Math.PI;while(da<-Math.PI)da+=2*Math.PI;tot+=da}}
  rad/=gpts.length;if(Math.abs(tot)>=3*Math.PI&&rad>=18&&rad<=260){gpts=[];gcool=now+2500;masGoto(e.clientX+36,e.clientY+24,1,'happy')}}}
function setPos(x,y,d){const el=$('#mas');el.style.transitionDuration=d+'s';el.style.transform=`translate(${x}px,${y}px)`}
function wander(){const m=S.prefs.mas||{},sp=m.sp??1;
 if(m.on===false||!sp||!$('#chat').hidden||Date.now()<masHold||matchMedia('(prefers-reduced-motion:reduce)').matches)return setTimeout(wander,2500);
 const sz=m.sz||80,x=8+Math.random()*Math.max(10,innerWidth-sz-16),y=70+Math.random()*Math.max(10,innerHeight-sz-190),d=Math.hypot(x-mp.x,y-mp.y),dur=Math.max(1.5,Math.min(10,d/(45*sp))),mb=$('#mas .mb'),el=$('#mas');
 mb.style.rotate=(x>mp.x?6:-6)+'deg';mp={x,y};el.classList.add('walk');setPos(x,y,dur);
 setTimeout(()=>{el.classList.remove('walk');mb.style.rotate='0deg'},dur*1000);setTimeout(wander,dur*1000+2000+Math.random()*3500)}
function mascotCard(){const m=S.prefs.mas||{},ch=(f,o,def)=>`<div class="seg">${o.map(([v,l])=>`<button class="${(m[f]||def)===v?'on':''}" data-a="mps" data-p="${f}" data-v="${v}">${l}</button>`).join('')}</div>`,cp=(f,def,l)=>`<label class="mu" style="display:flex;align-items:center;gap:6px"><input type="color" data-mp="${f}" value="${m[f]||def}" style="flex:none;width:40px;height:32px;padding:2px">${l}</label>`;
 return `<div class="glass card"><h2>🐾 Mascote IA</h2><div class="seg"><button class="${m.on===false?'':'on'}" data-a="mon">${m.on===false?'Mascote oculto — mostrar':'Mascote ativo'}</button></div>
 <input data-mp="name" placeholder="Nome do mascote (Bicetinho)" value="${esc(m.name||'')}" maxlength="14" style="width:100%;margin-bottom:10px">
 <div class="mu">Forma</div>${ch('sh',[['puff','Bolinha'],['blob','Blob'],['cat','Gatinho'],['bunny','Coelho'],['robot','Robô'],['ghost','Fantasma']],'puff')}
 <div class="mu">Acessório</div>${ch('ac',[['none','Nenhum'],['hat','Chapéu'],['crown','Coroa'],['glasses','Óculos'],['bow','Laço'],['phones','Fones']],'none')}
 <div class="mu">Expressão</div>${ch('mo',[['happy','Feliz'],['neutral','Neutro'],['wow','Surpreso']],'happy')}
 <div class="mu">Acessórios punk</div><div class="seg">${[['mohawk','Crista'],['bandana','Bandana'],['collar','Coleira de spikes'],['rings','Argolas'],['pierce','Piercings'],['chain','Corrente']].map(([v,l])=>`<button class="${(m.px||[]).includes(v)?'on':''}" data-a="mtog" data-p="px" data-v="${v}">${l}</button>`).join('')}</div>
 <div class="mu">Maquiagem</div><div class="seg">${[['liner','Delineado'],['shadow','Sombra esfumada'],['lips','Batom escuro'],['war','Marcas de guerra'],['tear','Lágrima'],['star','Estrela']].map(([v,l])=>`<button class="${(m.mk||[]).includes(v)?'on':''}" data-a="mtog" data-p="mk" data-v="${v}">${l}</button>`).join('')}</div>
 <div class="mu">Personalidade da IA</div>${ch('pe',[['fofo','Fofo'],['objetivo','Objetivo'],['animado','Animado'],['zen','Zen']],'fofo')}
 <div style="display:flex;gap:14px;flex-wrap:wrap;margin:8px 0">${cp('c','#ffadd0','Corpo')}${cp('c2','#ffffff','Barriga')}${cp('fc','#ff4f7b','Pés')}${cp('ec','#1c1f4a','Olhos')}${cp('pkc','#ff2d95','Crista')}${cp('mk1','#111111','Delineado')}${cp('mk2','#7b2cff','Sombra/batom')}</div>
 <div class="row"><div class="g t">Tamanho</div><input type="range" min="48" max="150" value="${m.sz||80}" data-mp="sz"></div>
 <div class="row"><div class="g t">Velocidade do passeio (0 = parado)</div><input type="range" min="0" max="3" step="0.5" value="${m.sp??1}" data-mp="sp"></div>
 <div class="row"><div class="g t">Bochechas rosadas</div><input type="checkbox" data-mp="bl" ${m.bl!==false?'checked':''} style="flex:none"></div><div class="row"><div class="g t">Barriga${(m.sh||'puff')==='puff'?' (a Bolinha começa sem)':''}</div><input type="checkbox" data-mp="bel" ${((m.sh||'puff')==='puff'?m.bel===true:m.bel!==false)?'checked':''} style="flex:none"></div><div class="row"><div class="g t">Reagir ao mouse (círculos chamam · vai e vem afasta)</div><input type="checkbox" data-mp="gs" ${m.gs!==false?'checked':''} style="flex:none"></div></div>`}
/* ---------- Chat com a IA ---------- */
function addMsg(r,t){const d=document.createElement('div');d.className='mg '+r;d.textContent=t;$('#cm').append(d);$('#cm').scrollTop=1e9;return d}
function openChat(){$('#chat').hidden=false;if(!$('#cm').children.length)addMsg('b','Oi! Eu sou '+((S.prefs.mas||{}).name||'Bicetinho')+' 👋 Posso agendar eventos, criar tarefas, lançar gastos, definir metas, alarmes e orçamentos… é só pedir!');$('#ci').focus()}
function ctxSummary(){const t=today(),m=t.slice(0,7),f=k=>S.fin.filter(x=>x.date.startsWith(m)&&x.type===k).reduce((a,x)=>a+x.val,0);
 return JSON.stringify({eventos:S.events.filter(e=>e.date>=t).sort((a,b)=>(a.date+a.time).localeCompare(b.date+b.time)).slice(0,8).map(e=>e.date+' '+e.time+' '+e.title),tarefas_abertas:S.tasks.filter(x=>!x.done).slice(0,8).map(x=>x.title+(x.due?' ('+x.due+')':'')),metas:S.goals.map(g=>g.title+' '+g.cur+'/'+g.target),orcamentos:S.budget.map(b=>b.cat+': '+b.limit),mes:{entradas:f('in'),saidas:f('out')},alarmes:S.alarms.filter(a=>a.on).map(a=>a.time+' '+a.label)})}
function tools(){const s={type:'string'},n={type:'number'},o=(p,r)=>({type:'object',properties:p,required:r});
 return [
 {name:'add_event',description:'Agenda um evento. date em AAAA-MM-DD, time em HH:MM (opcional).',inputSchema:o({title:s,date:s,time:s},['title','date']),execute:i=>{add('events',{title:i.title,date:i.date,time:i.time||''});return 'Evento criado'}},
 {name:'add_task',description:'Cria uma tarefa. priority: a (alta), m (média) ou b (baixa). due em AAAA-MM-DD (opcional).',inputSchema:o({title:s,priority:s,due:s},['title']),execute:i=>{add('tasks',{title:i.title,pri:['a','m','b'].includes(i.priority)?i.priority:'m',due:i.due||'',done:false});return 'Tarefa criada'}},
 {name:'complete_task',description:'Conclui a tarefa aberta cujo título contém o texto.',inputSchema:o({text:s},['text']),execute:i=>{const x=S.tasks.find(t=>!t.done&&t.title.toLowerCase().includes(String(i.text).toLowerCase()));if(!x)return 'Tarefa não encontrada';x.done=true;save();return 'Concluída: '+x.title}},
 {name:'add_transaction',description:'Lança uma entrada (type in) ou saída (type out). value positivo em reais; date AAAA-MM-DD opcional.',inputSchema:o({type:s,description:s,value:n,category:s,date:s},['type','description','value']),execute:i=>{add('fin',{type:i.type==='in'?'in':'out',desc:i.description,val:Math.abs(+i.value),cat:i.category||categorize(i.description),date:i.date||today()});return 'Lançamento criado'}},
 {name:'add_goal',description:'Cria uma meta com valor alvo e unidade opcional.',inputSchema:o({title:s,target:n,unit:s},['title','target']),execute:i=>{add('goals',{title:i.title,target:+i.target,unit:i.unit||'',cur:0});return 'Meta criada'}},
 {name:'add_alarm',description:'Cria um alarme em HH:MM. frequency: daily (padrão), weekdays, weekends ou once (com date AAAA-MM-DD opcional).',inputSchema:o({time:s,label:s,frequency:s,date:s},['time']),execute:i=>{add('alarms',{time:i.time,label:i.label||'Alarme',on:true,snd:'',freq:['daily','weekdays','weekends','once'].includes(i.frequency)?i.frequency:'daily',date:i.date||'',days:[]});return 'Alarme criado'}},
 {name:'set_budget',description:'Define o limite mensal de uma categoria de gastos.',inputSchema:o({category:s,limit:n},['category','limit']),execute:i=>{const x=S.budget.find(b=>b.cat.toLowerCase()===String(i.category).toLowerCase());if(x)x.limit=+i.limit;else S.budget.push({id:uid(),cat:i.category,limit:+i.limit});save();return 'Orçamento definido'}},
 {name:'set_financial_plan',description:'Define renda mensal planejada e/ou meta de poupança mensal.',inputSchema:o({income:n,save:n},[]),execute:i=>{S.fp={income:i.income??S.fp.income,save:i.save??S.fp.save};save();return 'Plano financeiro atualizado'}},
 {name:'add_plan',description:'Cria um plano (checklist) com etapas.',inputSchema:o({title:s,steps:{type:'array',items:s}},['title']),execute:i=>{add('plans',{title:i.title,items:(i.steps||[]).map(t=>({id:uid(),t,done:false}))});return 'Plano criado'}},
 {name:'add_routine',description:'Adiciona item de rotina diária. time HH:MM opcional; days = lista de 0 (domingo) a 6 (sábado), padrão todos os dias.',inputSchema:o({title:s,time:s,days:{type:'array',items:n}},['title']),execute:i=>{add('routine',{title:i.title,time:i.time||'',days:(i.days&&i.days.length?i.days:[0,1,2,3,4,5,6]),log:{}});return 'Item de rotina criado'}},
 {name:'add_fixed_expense',description:'Cadastra gasto fixo mensal com dia limite de pagamento (1 a 31).',inputSchema:o({name:s,value:n,day:n,category:s},['name','value','day']),execute:i=>{add('fixed',{name:i.name,val:Math.abs(+i.value),day:Math.min(31,Math.max(1,Math.round(+i.day))),cat:i.category||'Fixos',paid:{}});return 'Gasto fixo cadastrado'}},
 {name:'open_screen',description:'Abre uma tela: home, agenda, tasks, plans, goals, fin, alarms ou set.',inputSchema:o({screen:s},['screen']),execute:i=>{if(V[i.screen]){view=i.screen;render()}return 'ok'}},
 {name:'set_theme',description:'Muda a cor de destaque (hex #rrggbb) e/ou o modo (auto, light, dark).',inputSchema:o({accent:s,mode:s},[]),execute:i=>{if(/^#[0-9a-f]{6}$/i.test(i.accent||''))S.prefs.ac=i.accent;if(['auto','light','dark'].includes(i.mode))S.prefs.mode=i.mode;save();return 'Tema atualizado'}}]}
async function ask(){const inp=$('#ci'),t=inp.value.trim();if(!t||busy)return;inp.value='';
 const hist=chat.slice(-10).map(m=>(m.r==='u'?'Usuário: ':'Você: ')+m.t).join('\n');chat.push({r:'u',t});addMsg('u',t);busy=true;const b=addMsg('b','…');
 try{const sm=await claude.use('sample');if(!sm)throw{code:'none'};const m=S.prefs.mas||{},PE={fofo:'fofa e carinhosa, com emojis moderados',objetivo:'direta e objetiva',animado:'super animada e motivadora',zen:'calma e zen'},n=new Date();
  const prompt=`Você é ${m.name||'Bicetinho'}, o mascote do app de gestão de tempo "TEDEAGA". Personalidade: ${PE[m.pe||'fofo']}. Responda em português do Brasil, em no máximo 3 frases curtas. Use as ferramentas para executar pedidos do usuário (eventos, tarefas, lançamentos financeiros, metas, alarmes, orçamentos, planos, abrir telas, tema). Hoje é ${today()} (${n.toLocaleDateString('pt-BR',{weekday:'long'})}), agora são ${pad2(n.getHours())}:${pad2(n.getMinutes())}; converta datas relativas para AAAA-MM-DD. Se faltar informação essencial, pergunte. Nunca invente dados nem diga que fez algo sem usar a ferramenta. Dados atuais do app: ${ctxSummary()}\n\nConversa recente:\n${hist}\nUsuário: ${t}`;
  const r=await sm(prompt,{cache:false,tools:tools(),onText:({text})=>{b.textContent=text||'…'}});b.textContent=r.text||'Pronto! ✅';chat.push({r:'b',t:b.textContent})}
 catch(e){b.textContent=e&&e.code==='not_granted'?'Preciso da sua permissão para usar a IA. Envie de novo e aceite o aviso.':e&&e.code==='rate_limited'?'Muitas mensagens seguidas! Espere um pouquinho.':e&&e.code==='none'?'A IA não está disponível.':e&&(e.code==='nokey'||e.code==='badkey')?'Configure sua chave da API Anthropic em Ajustes > Chave da IA.':'Ops, algo deu errado. Tente de novo.'}
 busy=false}
function initMas(){const el=$('#mas');mp={x:Math.max(8,innerWidth-120),y:Math.max(80,innerHeight-300)};setPos(mp.x,mp.y,0);
 addEventListener('pointermove',e=>{look(e.clientX,e.clientY);masGesture(e)});
 el.addEventListener('click',openChat);$('#ci').addEventListener('keydown',e=>{if(e.key==='Enter')ask()});
 document.addEventListener('input',e=>{const t=e.target;if(t.dataset.sl){S.prefs[t.dataset.sl]=+t.value;applyTheme()}else if(t.dataset.mp&&t.type==='range'){S.prefs.mas=S.prefs.mas||{};S.prefs.mas[t.dataset.mp]=+t.value;applyTheme()}});
 look(innerWidth/2,innerHeight/2);setTimeout(wander,2500)}

/* ===== Widgets, gastos fixos, rotina, áudios locais, efeitos ===== */
const hmNow=()=>new Date().toLocaleTimeString('pt-BR',{hour:'2-digit',minute:'2-digit'});
const DOW=['Dom','Seg','Ter','Qua','Qui','Sex','Sáb'];
const WT=[['note','📝 Nota'],['countdown','⏳ Contagem regressiva'],['counter','🔢 Contador'],['clock','🕐 Relógio'],['goal','🎯 Meta'],['routine','🔁 Rotina de hoje'],['balance','💰 Saldo do mês'],['next','📅 Próximos eventos']];
function dayStr(off){const d=new Date();d.setDate(d.getDate()+off);return d.getFullYear()+'-'+pad2(d.getMonth()+1)+'-'+pad2(d.getDate())}
function rtSched(it,d){return(it.days||[0,1,2,3,4,5,6]).includes(new Date(d+'T12:00').getDay())}
function rtToday(){const t=today(),L=(S.routine||[]).filter(i=>rtSched(i,t));return{L,total:L.length,done:L.filter(i=>(i.log||{})[t]).length}}
function streak(it){let n=0;for(let o=0;o>-400;o--){const d=dayStr(o);if(!rtSched(it,d))continue;if((it.log||{})[d])n++;else if(o!==0)break}return n}
function rtRow(i,t){const on=(i.log||{})[t];return `<div class="row ${on?'done':''}"><button class="chk" data-a="rt" data-id="${i.id}">${on?'✓':''}</button><div class="g t">${esc(i.title)}</div><span class="mu">${i.time||''}</span><span class="pill">🔥 ${streak(i)}</span></div>`}
function monthBal(){const m=today().slice(0,7),f=k=>S.fin.filter(x=>x.date.startsWith(m)&&x.type===k).reduce((a,x)=>a+x.val,0);return f('in')-f('out')}
function wBody(w){const t=w.type;
 if(t==='note')return `<div style="white-space:pre-wrap">${esc(w.text||'')}</div>`;
 if(t==='countdown'){if(!w.date)return '<div class="mu">Defina uma data.</div>';const d=Math.round((new Date(w.date+'T12:00')-new Date(today()+'T12:00'))/864e5);return `<div class="big">${d>0?d+(d>1?' dias':' dia'):d===0?'É hoje! 🎉':'Passou há '+(-d)+' d'}</div><div class="mu">${new Date(w.date+'T12:00').toLocaleDateString('pt-BR',{day:'numeric',month:'long',year:'numeric'})}</div>`}
 if(t==='counter'){const tg=+w.text||0;return `<div class="big">${w.v||0}${tg?' / '+tg:''}</div>${tg?`<div class="bar"><i style="width:${Math.min(100,(w.v||0)/tg*100)}%"></i></div>`:''}<div style="margin-top:8px;display:flex;gap:6px"><button class="pri" data-a="wc" data-id="${w.id}" data-d="-1">−</button><button class="pri" data-a="wc" data-id="${w.id}" data-d="1">+</button></div>`}
 if(t==='clock')return `<div class="big wclk">${hmNow()}</div><div class="mu">${new Date().toLocaleDateString('pt-BR',{weekday:'long',day:'numeric',month:'long'})}</div>`;
 if(t==='goal'){const g=find('goals',w.gid);if(!g)return '<div class="mu">Escolha uma meta existente.</div>';const p=Math.min(100,Math.round(g.cur/g.target*100));return `<div class="mu">${esc(g.title)}</div><div class="big">${p}%</div><div class="bar"><i style="width:${p}%"></i></div>`}
 if(t==='routine'){const r=rtToday();return `<div class="big">${r.done}/${r.total}</div><div class="bar"><i style="width:${r.total?r.done/r.total*100:0}%"></i></div>`}
 if(t==='balance'){const b=monthBal();return `<div class="big ${b<0?'exp':'inc'}">${brl(b)}</div>`}
 if(t==='next'){const L=S.events.filter(e=>e.date>=today()).sort((a,b)=>(a.date+a.time).localeCompare(b.date+b.time)).slice(0,3);return L.map(e=>`<div class="mu">${e.date.slice(8)}/${e.date.slice(5,7)} ${e.time||''} · ${esc(e.title)}</div>`).join('')||'<div class="mu">Sem eventos.</div>'}
 return ''}
function fxDue(){const n=new Date(),ym=today().slice(0,7),dim=new Date(n.getFullYear(),n.getMonth()+1,0).getDate(),t0=new Date(n.getFullYear(),n.getMonth(),n.getDate());return(S.fixed||[]).map(f=>{const day=Math.min(f.day,dim),diff=Math.round((new Date(n.getFullYear(),n.getMonth(),day)-t0)/864e5);return{...f,day,diff,paid:!!(f.paid&&f.paid[ym])}}).sort((a,b)=>a.day-b.day)}
function dueCard(){const L=fxDue().filter(x=>!x.paid&&x.diff<=7).slice(0,4);return `<div class="glass card"><h2>💸 Contas a vencer</h2>${L.map(x=>`<div class="row"><b>dia ${x.day}</b><div class="g t">${esc(x.name)}</div><span class="${x.diff<0?'exp':'mu'}">${x.diff<0?'atrasada':x.diff===0?'hoje':'em '+x.diff+' d'}</span></div>`).join('')||'<div class="mu">Nenhuma conta nos próximos 7 dias.</div>'}</div>`}
function rtCard(){const r=rtToday(),pend=r.L.filter(i=>!(i.log||{})[today()]).sort((a,b)=>(a.time||'99').localeCompare(b.time||'99')).slice(0,3);return `<div class="glass card"><h2>🔁 Rotina de hoje</h2><div class="big">${r.done}/${r.total}</div><div class="bar"><i style="width:${r.total?r.done/r.total*100:0}%"></i></div>${pend.map(i=>`<div class="mu" style="margin-top:4px">${i.time||'•'} ${esc(i.title)}</div>`).join('')}</div>`}
function wForm(){return `<div class="glass card"><h2>➕ Novo widget</h2><form data-f="wid"><select name="type">${WT.map(([k,l])=>`<option value="${k}">${l}</option>`).join('')}</select><input name="title" placeholder="Título"><input name="text" placeholder="Texto / meta do contador"><input name="date" type="date"><select name="gid"><option value="">— meta —</option>${S.goals.map(g=>`<option value="${g.id}">${esc(g.title)}</option>`).join('')}</select><input name="color" type="color" value="${S.prefs.ac}" style="flex:none;width:44px;padding:2px"><button class="pri">Criar</button></form><div class="mu">Nota usa o texto · contagem regressiva usa a data · contador usa o texto como meta numérica (opcional) · meta usa a seleção.</div></div>`}
function widgets(){return dueCard()+rtCard()+(S.widgets||[]).map(w=>`<div class="glass card" style="border-top:4px solid ${esc(w.color||'var(--ac)')}"><div class="top" style="margin:0 0 6px"><h2 style="margin:0">${esc(w.title||'')}</h2><span>${window.deskBtn?deskBtn(w.id):''}<button class="x" data-a="del" data-k="widgets" data-id="${w.id}">✕</button></span></div>${wBody(w)}</div>`).join('')+wForm()}
setInterval(()=>document.querySelectorAll('.wclk').forEach(e=>e.textContent=hmNow()),1000);
function fixedCard(){const L=fxDue(),tot=L.reduce((a,f)=>a+f.val,0),pg=L.filter(f=>f.paid).reduce((a,f)=>a+f.val,0),inc=(S.fp&&S.fp.income)||0;
 return `<div class="glass card"><h2>📌 Gastos fixos e vencimentos</h2><form data-f="fxd"><input name="name" placeholder="Conta (ex.: Aluguel)" required><input name="val" type="number" step="0.01" min="0" placeholder="Valor" required><input name="day" type="number" min="1" max="31" placeholder="Dia limite" required><input name="cat" placeholder="Categoria" value="Moradia"><button class="pri">Adicionar</button></form>
 <div class="grid"><div><div class="mu">Total fixo/mês</div><div class="big">${brl(tot)}</div>${inc?`<div class="mu">${Math.round(tot/inc*100)}% da renda planejada</div>`:''}</div><div><div class="mu">Já pago</div><div class="big inc">${brl(pg)}</div></div><div><div class="mu">A pagar</div><div class="big exp">${brl(tot-pg)}</div></div></div>
 <div style="margin-top:10px">${L.map(f=>`<div class="row ${f.paid?'done':''}"><button class="chk" data-a="fpay" data-id="${f.id}">${f.paid?'✓':''}</button><div class="g"><div class="t">${esc(f.name)}</div><div class="mu">vence dia ${f.day} · ${esc(f.cat)} · ${f.paid?'pago':f.diff<0?'atrasada há '+(-f.diff)+' d':f.diff===0?'vence hoje':'em '+f.diff+' d'}</div></div><b>${brl(f.val)}</b><button class="x" data-a="del" data-k="fixed" data-id="${f.id}">✕</button></div>`).join('')||'<div class="mu">Cadastre aluguel, internet, assinaturas… e acompanhe os dias limite. Ao marcar como pago, o lançamento entra nas finanças.</div>'}</div></div>`}
function libCard(){const L=S.prefs.lib||[],cur=S.prefs.snd;return `<div class="glass card"><h2>🎵 Meus áudios</h2><div class="mu" style="margin-bottom:8px">Adicione arquivos do seu computador (MP3, WAV, OGG ou M4A; até 1,5 MB cada, no máximo 8) e escolha qualquer um como som padrão ou em cada alarme.</div><div class="seg"><button data-a="libup">⬆️ Adicionar áudios</button></div>${L.map(l=>`<div class="row"><div class="g t">🎵 ${esc(l.name)}</div><button class="x" data-a="psnd" data-v="u:${l.id}">▶</button><button class="pri" data-a="snd" data-v="u:${l.id}" style="${cur==='u:'+l.id?'':'background:var(--mu)'}">${cur==='u:'+l.id?'Padrão':'Usar'}</button><button class="x" data-a="libdel" data-id="${l.id}">✕</button></div>`).join('')||'<div class="mu">Nenhum áudio ainda.</div>'}</div>`}
/* efeitos sobre o papel de parede */
const FXS=[['none','Nenhum'],['ocean','🌊 Fundo do mar'],['bubbles','🫧 Bolhas'],['snow','❄️ Neve'],['fire','✨ Vaga-lumes'],['rain','🌧️ Chuva suave'],['aurora','🌌 Aurora']];
let fxs={key:'',raf:0,ps:[],last:0,W:0,H:0,sprite:null,rs:0};
function fxCard(){const p=S.prefs;return `<div class="glass card"><h2>🌊 Efeitos sobre o papel de parede</h2><div class="seg">${FXS.map(([k,l])=>`<button class="${(p.fx||'none')===k?'on':''}" data-a="fx" data-v="${k}">${l}</button>`).join('')}</div><div class="row"><div class="g t">Intensidade</div><input type="range" min="10" max="100" value="${p.fxi??50}" data-sl="fxi"></div><div class="row"><div class="g t">Distorção tranquila (ondulação do papel de parede)</div><input type="range" min="0" max="20" value="${p.fxd??(p.fx==='ocean'?8:0)}" data-sl="fxd"></div><div class="mu">Os efeitos funcionam com ou sem papel de parede; a distorção precisa de uma imagem enviada.</div></div>`}
function fxInit(){const p=S.prefs,m=p.fx,c=$('#fxc'),k=(p.fxi??50)/50;fxs.W=c.width=innerWidth;fxs.H=c.height=innerHeight;
 const cfg={bubbles:[14,4,16,.25,.9],ocean:[10,2,9,.2,.6],snow:[60,1,3.2,.3,1],rain:[70,4,10,.6,1.4],fire:[22,2,4.5,0,0]}[m];
 if(!cfg){fxs.ps=[];return}const n=Math.round(cfg[0]*k),R=(a,b)=>a+Math.random()*(b-a);
 fxs.ps=Array.from({length:n},()=>({x:R(0,fxs.W),y:R(0,fxs.H),r:R(cfg[1],cfg[2]),v:R(cfg[3],cfg[4]),ph:R(0,6.28)}));
 const s=document.createElement('canvas');s.width=s.height=32;const g=s.getContext('2d'),rg=g.createRadialGradient(16,16,0,16,16,16);rg.addColorStop(0,'rgba(255,240,150,1)');rg.addColorStop(.35,'rgba(255,220,90,.45)');rg.addColorStop(1,'rgba(255,220,90,0)');g.fillStyle=rg;g.fillRect(0,0,32,32);fxs.sprite=s}
function fxLoop(t){fxs.raf=requestAnimationFrame(fxLoop);if(document.hidden||t-fxs.last<33)return;fxs.last=t;const p=S.prefs,m=p.fx,x=$('#fxc').getContext('2d'),W=fxs.W,H=fxs.H,k=(p.fxi??50)/50;x.clearRect(0,0,W,H);
 if(m==='ocean'){const g=x.createLinearGradient(0,0,0,H);g.addColorStop(0,'rgba(80,200,230,'+.10*k+')');g.addColorStop(1,'rgba(5,40,90,'+.32*k+')');x.fillStyle=g;x.fillRect(0,0,W,H);
  for(let i=0;i<6;i++){const x0=(i+.5)*W/6+Math.sin(t/2600+i*1.7)*70,w=40+30*Math.sin(t/3100+i),gg=x.createLinearGradient(x0,0,x0+W*.12,H*.8);gg.addColorStop(0,'rgba(190,245,255,'+.14*k+')');gg.addColorStop(1,'rgba(190,245,255,0)');x.fillStyle=gg;x.beginPath();x.moveTo(x0-w/2,0);x.lineTo(x0+w/2,0);x.lineTo(x0+W*.12+w,H*.8);x.lineTo(x0+W*.12-w,H*.8);x.fill()}}
 if(m==='aurora'){for(let b=0;b<3;b++){const col=['rgba(80,255,170,','rgba(120,140,255,','rgba(220,100,255,'][b],gg=x.createLinearGradient(0,H*.1,0,H*.6);gg.addColorStop(0,col+'0)');gg.addColorStop(.5,col+.22*k+')');gg.addColorStop(1,col+'0)');x.fillStyle=gg;x.beginPath();x.moveTo(0,H*.6);for(let i=0;i<=40;i++)x.lineTo(i/40*W,H*(.3+b*.08)+Math.sin(i*.35+t/2500+b*2)*H*.07+Math.sin(i*.12+t/4000)*H*.05);x.lineTo(W,H*.6);x.closePath();x.fill()}}
 for(const q of fxs.ps){
  if(m==='bubbles'||m==='ocean'){q.y-=q.v;q.x+=Math.sin(t/900+q.ph)*.4;if(q.y<-q.r*2){q.y=H+q.r*2;q.x=Math.random()*W}x.beginPath();x.arc(q.x,q.y,q.r,0,6.283);x.fillStyle='rgba(255,255,255,.07)';x.fill();x.strokeStyle='rgba(255,255,255,'+Math.min(.8,.45*k)+')';x.lineWidth=1.4;x.stroke();x.beginPath();x.arc(q.x-q.r*.35,q.y-q.r*.35,q.r*.22,0,6.283);x.fillStyle='rgba(255,255,255,.55)';x.fill()}
  else if(m==='snow'){q.y+=q.v;q.x+=Math.sin(t/1200+q.ph)*.5;if(q.y>H+5){q.y=-5;q.x=Math.random()*W}x.beginPath();x.arc(q.x,q.y,q.r,0,6.283);x.fillStyle='rgba(255,255,255,'+Math.min(.9,.55*k+.1)+')';x.fill()}
  else if(m==='rain'){q.y+=q.v*7;q.x+=q.v*1.6;if(q.y>H){q.y=-20;q.x=Math.random()*W}x.beginPath();x.moveTo(q.x,q.y);x.lineTo(q.x+2.5,q.y+q.r*3);x.strokeStyle='rgba(200,225,255,'+Math.min(.6,.28*k)+')';x.lineWidth=1;x.stroke()}
  else if(m==='fire'){q.x+=Math.cos(q.ph+t/2500)*.4;q.y+=Math.sin(q.ph*2+t/3000)*.35;x.globalAlpha=Math.min(1,(.35+.65*Math.abs(Math.sin(t/900+q.ph*3)))*k);x.drawImage(fxs.sprite,q.x-q.r*3,q.y-q.r*3,q.r*6,q.r*6);x.globalAlpha=1}}}
function fxApply(){const p=S.prefs,c=$('#fxc');if(!c)return;const dist=p.fxd??(p.fx==='ocean'?8:0),d=$('#wobd');if(d)d.setAttribute('scale',dist);
 $('#wp').style.filter=(dist>0&&p.wall)?'blur(var(--wb,0px)) url(#wob)':'';
 if(!fxs.rs){fxs.rs=1;addEventListener('resize',()=>{fxs.key='';fxApply()})}
 const key=(p.fx||'none')+'|'+(p.fxi??50);if(fxs.key===key)return;fxs.key=key;cancelAnimationFrame(fxs.raf);fxs.raf=0;
 if((p.fx||'none')==='none'||matchMedia('(prefers-reduced-motion:reduce)').matches){c.getContext('2d').clearRect(0,0,c.width,c.height);return}
 fxInit();fxs.raf=requestAnimationFrame(fxLoop)}
